package com.termux.app.workspace;
import android.app.*;import android.content.*;import android.content.pm.*;import android.speech.*;import android.widget.*;import android.os.*;import android.provider.Settings;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadow.api.Shadow;import java.util.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,shadows=AgentSpeechServiceTest.Engine.class) public class AgentSpeechServiceTest {
 @Implements(SpeechRecognizer.class) public static class Engine {static RecognitionListener listener;static int starts,destroys,stops,cancels,creates,checks;static boolean available=true;static RuntimeException createFailure,startFailure;@Implementation protected static boolean isRecognitionAvailable(Context c){checks++;return available;}@Implementation protected static SpeechRecognizer createSpeechRecognizer(Context c){creates++;if(createFailure!=null)throw createFailure;return Shadow.newInstanceOf(SpeechRecognizer.class);}@Implementation protected static SpeechRecognizer createSpeechRecognizer(Context c,ComponentName n){throw new AssertionError("No explicit provider");}@Implementation protected void setRecognitionListener(RecognitionListener l){listener=l;}@Implementation protected void startListening(Intent i){assertTrue(i.getBooleanExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false));starts++;if(startFailure!=null)throw startFailure;}@Implementation protected void stopListening(){stops++;}@Implementation protected void cancel(){cancels++;}@Implementation protected void destroy(){destroys++;}}
 static void configure(Activity a){Engine.available=true;Engine.createFailure=Engine.startFailure=null;Settings.Secure.putString(a.getContentResolver(),"voice_recognition_service","system.speech/.Service");ServiceInfo info=Shadows.shadowOf(a.getPackageManager()).addServiceIfNotPresent(new ComponentName("system.speech","system.speech.Service"));info.enabled=true;info.exported=true;info.applicationInfo.enabled=true;Shadows.shadowOf(a.getPackageManager()).addOrUpdateService(info);Shadows.shadowOf((Application)a.getApplication()).grantPermissions(android.Manifest.permission.RECORD_AUDIO);}
 static Bundle words(String text){Bundle b=new Bundle();b.putStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION,new ArrayList<>(Arrays.asList(text)));return b;}
 @Before public void reset(){Engine.starts=Engine.destroys=Engine.stops=Engine.cancels=Engine.creates=Engine.checks=0;Engine.available=true;Engine.createFailure=Engine.startFailure=null;Engine.listener=null;}
 @Test public void partialIsPreviewAndFinalAppendsOnlyOnceWithoutExternalActivity(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();configure(a);EditText input=new EditText(a);input.setText("draft");input.setSelection(0,input.length());List<String> notices=new ArrayList<>(),states=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->"one",notices::add);d.presentation((text,active,stop,cancel)->states.add(text));d.start();d.start();assertEquals(1,Engine.starts);assertNull(Shadows.shadowOf(a).getNextStartedActivityForResult());RecognitionListener listener=Engine.listener;listener.onReadyForSpeech(new Bundle());listener.onPartialResults(words("first"));listener.onPartialResults(words("first words"));assertEquals("draft",input.getText().toString());assertTrue(states.get(states.size()-1).contains("first words"));d.stop();assertEquals(1,Engine.stops);listener.onResults(words("first words"));listener.onResults(words("duplicate"));assertEquals("draft first words",input.getText().toString());assertTrue(Engine.destroys>0);assertTrue(notices.isEmpty());}
 @Test public void errorCancelSwitchAndEditedDraftRetainText(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();configure(a);EditText input=new EditText(a);input.setText("keep");String[] owner={"one"};List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->owner[0],notices::add);d.start();RecognitionListener old=Engine.listener;d.clear();d.start();old.onResults(words("late"));assertEquals("keep",input.getText().toString());Engine.listener.onError(SpeechRecognizer.ERROR_NETWORK);assertEquals(1,notices.size());assertEquals("keep",input.getText().toString());d.start();owner[0]="two";d.ownerChanged();Engine.listener.onResults(words("wrong chat"));assertEquals("keep",input.getText().toString());d.start();input.setText("edited");Engine.listener.onResults(words("discard"));assertEquals("edited",input.getText().toString());d.start();d.background();Engine.listener.onResults(words("hidden"));assertEquals("edited",input.getText().toString());}

 @Test public void permissionComesFirstAndEmptyDefaultDoesNotPreventARealPlatformAttempt(){
  Activity a=Robolectric.buildActivity(Activity.class).setup().get();EditText input=new EditText(a);input.setText("keep");List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->"one",notices::add);
  Settings.Secure.putString(a.getContentResolver(),"voice_recognition_service",null);Shadows.shadowOf((Application)a.getApplication()).denyPermissions(android.Manifest.permission.RECORD_AUDIO);
  d.start();assertEquals(0,Engine.creates);assertEquals(0,Engine.checks);org.robolectric.shadows.ShadowActivity.PermissionsRequest requested=Shadows.shadowOf(a).getLastRequestedPermission();assertEquals(AgentDictation.AUDIO_REQUEST,requested.requestCode);assertArrayEquals(new String[]{android.Manifest.permission.RECORD_AUDIO},requested.requestedPermissions);
  d.permissionResult(AgentDictation.AUDIO_REQUEST);assertEquals(0,Engine.starts);assertTrue(notices.get(0).contains("PERMISSION_DENIED=-1"));
  d.start();Shadows.shadowOf((Application)a.getApplication()).grantPermissions(android.Manifest.permission.RECORD_AUDIO);d.permissionResult(AgentDictation.AUDIO_REQUEST);assertEquals(1,Engine.starts);
  Engine.listener.onError(SpeechRecognizer.ERROR_CLIENT);String error=notices.get(1);assertTrue(error.contains("onError: 5 (ERROR_CLIENT)"));assertTrue(error.contains("voice_recognition_service: <null>"));assertTrue(error.contains("isRecognitionAvailable: true"));assertTrue(error.contains("RECORD_AUDIO: GRANTED"));assertEquals("keep",input.getText().toString());
 }
 @Test public void unavailableDiscoveryStillReportsThePlatformErrorInsteadOfInventingIt(){
  Activity a=Robolectric.buildActivity(Activity.class).setup().get();configure(a);Engine.available=false;EditText input=new EditText(a);input.setText("draft");List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->"one",notices::add);d.start();assertEquals(1,Engine.starts);
  Engine.listener.onError(SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS);assertTrue(notices.get(0).contains("onError: 9 (ERROR_INSUFFICIENT_PERMISSIONS)"));assertTrue(notices.get(0).contains("isRecognitionAvailable: false"));assertTrue(notices.get(0).contains("RECORD_AUDIO: GRANTED"));assertEquals("draft",input.getText().toString());
 }
 @Test public void synchronousCreateAndStartFailuresHaveTheirOwnStage(){
  Activity a=Robolectric.buildActivity(Activity.class).setup().get();configure(a);EditText input=new EditText(a);input.setText("draft");List<String> notices=new ArrayList<>();AgentDictation d=new AgentDictation(a,input,()->"one",notices::add);
  Engine.createFailure=new UnsupportedOperationException();d.start();assertTrue(notices.get(0).startsWith("createSpeechRecognizer: UnsupportedOperationException"));assertEquals(0,Engine.starts);
  Engine.createFailure=null;Engine.startFailure=new IllegalStateException();d.start();assertTrue(notices.get(1).startsWith("startListening: IllegalStateException"));assertEquals("draft",input.getText().toString());
 }
 @Test public void switchingChatWhilePermissionIsPendingDoesNotStartTheOldCapture(){
  Activity a=Robolectric.buildActivity(Activity.class).setup().get();Shadows.shadowOf((Application)a.getApplication()).denyPermissions(android.Manifest.permission.RECORD_AUDIO);EditText input=new EditText(a);input.setText("keep");String[] owner={"one"};AgentDictation d=new AgentDictation(a,input,()->owner[0],message->fail(message));d.start();owner[0]="two";d.ownerChanged();Shadows.shadowOf((Application)a.getApplication()).grantPermissions(android.Manifest.permission.RECORD_AUDIO);d.permissionResult(AgentDictation.AUDIO_REQUEST);assertEquals(0,Engine.creates);assertEquals("keep",input.getText().toString());
 }
}
